def process(extract_identity_theft) -> pd.DataFrame:
    data = extract_identity_theft.sort_values('Year')
    reports_2001 = data[data['Year'] == 2001]['Identity_Theft'].values[0]
    reports_2024 = data[data['Year'] == 2024]['Identity_Theft'].values[0]
    ratio = reports_2024 / reports_2001
    return pd.DataFrame({'Ratio_2024_vs_2001': [round(ratio, 4)]})
